L["Blizzard's own character sheet as the game draws it; WoW Forever keeps the item text beside the slots, and the stat colors stay with the EllesmereUI look."] = "A própria ficha de personagem da Blizzard como o jogo a desenha; WoW Forever mantém o texto dos itens ao lado dos espaços, e as cores dos atributos seguem o visual do EllesmereUI."
L["Blizzard's own character sheet with the EllesmereUI stats, slot text and socket panel added; the Calc tab stays with the EllesmereUI look."] = "A própria ficha de personagem da Blizzard com os atributos, texto dos espaços e painel de engastes do EllesmereUI; a aba Calc segue o visual do EllesmereUI."
L["Blizzard's own chat window, tabs and input box, or the same window with the classic tab art, with every EllesmereUI chat feature."] = "A própria janela de bate-papo, abas e caixa de entrada da Blizzard, ou a mesma janela com a arte clássica das abas, com todos os recursos de bate-papo do EllesmereUI."
L["Blizzard's own frame and button art, with EllesmereUI's features."] = "A própria arte de quadros e botões da Blizzard, com os recursos do EllesmereUI."
L["Blizzard's own friends window and cards, with the EllesmereUI class icons, class-coloured names and region icons added. Both stock styles look the same here."] = "A própria janela e cartões de amigos da Blizzard, com os ícones de classe, nomes na cor da classe e ícones de região do EllesmereUI. Ambos os estilos padrão ficam iguais aqui."
L["Blizzard's own tracker, with every EllesmereUI tracker feature. Both stock styles look the same here."] = "O próprio rastreador da Blizzard, com todos os recursos de rastreador do EllesmereUI. Ambos os estilos padrão ficam iguais aqui."
L["Blizzard's raid frame edge and highlights, or the classic ones, with every EllesmereUI raid frame feature."] = "Borda e destaques dos quadros de raide da Blizzard, ou os clássicos, com todos os recursos de quadro de raide do EllesmereUI."
L["Blizzard's round minimap and header, or the classic ring, with every EllesmereUI minimap feature."] = "Minimapa redondo e cabeçalho da Blizzard, ou o anel clássico, com todos os recursos de minimapa do EllesmereUI."
L["Blizzard's rounded button art, or the classic square slots, with every EllesmereUI bar feature."] = "Arte arredondada de botões da Blizzard, ou os espaços quadrados clássicos, com todos os recursos de barra do EllesmereUI."
L["Blizzard's rounded cooldown icons, or the classic square slots, with every EllesmereUI icon feature."] = "Ícones de recarga arredondados da Blizzard, ou os espaços quadrados clássicos, com todos os recursos de ícone do EllesmereUI."
L["Blizzard's windows now match the EllesmereUI theme with a WoW 2.0 Dark Theme, from the Dungeon Journal to the Auction House and beyond."] = "As janelas da Blizzard agora combinam com o tema do EllesmereUI com um Tema Escuro WoW 2.0, do Diário de Masmorras à Casa de Leilões e além."
