L["Color the health bar by how much health is left, instead of a flat color. Classic runs green at full health through yellow to red at empty. Custom Colors blends between the three stop swatches on this row -- full (100%), half (50%) and empty (0%). Class Reactive shows the class color at full health, bleeding into the 50% and 0% colors as the unit takes damage. Off leaves the flat Fill Color swatches in charge; either way the Gradient below still applies, running from whichever color this picks."] = "Colore a barra de vida pela vida restante, em vez de uma cor fixa. Clássico vai de verde com vida cheia, passando por amarelo, até vermelho quando vazia. Cores Personalizadas mescla as três amostras desta linha -- cheia (100%), metade (50%) e vazia (0%). Reativo à Classe mostra a cor da classe com vida cheia, passando para as cores de 50% e 0% conforme a unidade sofre dano. Desligado mantém as amostras de Cor de Preenchimento fixas; em ambos os casos o Gradiente abaixo ainda se aplica, partindo da cor escolhida aqui."
