L["Colors"] = "Cores"
L["Colors allied player bars using their class. Group/raid members are identified automatically; other allies are learned from target, mouseover or focus."] = "Colore as barras de jogadores aliados pela classe. Membros do grupo/raide são identificados automaticamente; outros aliados são aprendidos pelo alvo, passar o mouse ou foco."
L["Colors an attackable unit's level by difficulty, as the default UI does."] = "Colore o nível de uma unidade atacável pela dificuldade, como a interface padrão faz."
L["Colors are shared globally from the \"%1$s\" profile.\nSwitch to it (or set Pull Colors From to this profile) to edit."] = "As cores são compartilhadas globalmente do perfil \"%1$s\".\nMude para ele (ou defina Puxar Cores De para este perfil) para editar."
L["Colors group and raid member names inside Say, Yell, Party and Raid messages."] = "Colore os nomes de membros do grupo e da raide nas mensagens de Dizer, Gritar, Grupo e Raide."
L["Colors level text by difficulty, from grey (trivial) through green, yellow and orange to red (5+ levels above you)."] = "Colore o texto do nível pela dificuldade, do cinza (trivial) passando por verde, amarelo e laranja até vermelho (5+ níveis acima de você)."
L["Colors the bar text instead of the fill when the threshold applies."] = "Colore o texto da barra em vez do preenchimento quando o limite se aplica."
L["Colors the cast segment during which your interrupt will be available."] = "Colore o trecho do lançamento em que sua interrupção estará disponível."
L["Colors the dispel type borders with your Dispel Colors instead of Blizzard's."] = "Colore as bordas por tipo de dissipação com suas Cores de Dissipação em vez das da Blizzard."
L["Colors the number by threat status. Off shows it in white."] = "Colore o número pelo estado de ameaça. Desligado mostra em branco."
L["Colors the number when free slots drop below this many; the swatch picks the color. Zero turns it off."] = "Colore o número quando os espaços livres caem abaixo deste valor; a amostra escolhe a cor. Zero desliga."
L["Colors the strip behind the target's name by its reaction."] = "Colore a faixa atrás do nome do alvo pela reação dele."
