L["Hides the Add Category button at the bottom of the bag sidebar."] = "Oculta o botão Adicionar Categoria na parte inferior da barra lateral da bolsa."
L["Hides the default arena enemy frames while these are enabled."] = "Oculta os quadros de inimigos de arena padrão enquanto estes estiverem ativados."
L["Hides the EllesmereUI button from the game's Escape/pause menu."] = "Oculta o botão do EllesmereUI no menu Esc/pausa do jogo."
L["Hides the Objectives header and its minimize button at the top of the tracker."] = "Oculta o cabeçalho Objetivos e seu botão de minimizar no topo do rastreador."
L["Hides the Objectives header and its minimize button at the top of the tracker. When shown, it uses the Header Color with a divider in the Line Color."] = "Oculta o cabeçalho Objetivos e seu botão de minimizar no topo do rastreador. Quando mostrado, usa a Cor do Cabeçalho com um divisor na Cor da Linha."
L["Hides the resize handle on the main chat frame, preventing accidental resizing."] = "Oculta a alça de redimensionar do quadro principal de bate-papo, evitando redimensionamentos acidentais."
L["Hides the swipe and keeps the timer."] = "Oculta a varredura e mantém o cronômetro."
L["Hides the sync icons on the sidebar module list."] = "Oculta os ícones de sincronização na lista de módulos da barra lateral."
L["Hides the thin dividers between the messages, input field and sidebar."] = "Oculta os divisores finos entre as mensagens, o campo de digitação e a barra lateral."
L["Hides the Unlock Mode button from the game's Escape/pause menu. You can still toggle Unlock Mode from the EUI options panel."] = "Oculta o botão do Modo de Desbloqueio no menu Esc/pausa do jogo. Você ainda pode alternar o Modo de Desbloqueio no painel de opções do EUI."
L["Hides this element while you are on a skyriding (glide-capable) mount, where Blizzard shows its vigor HUD."] = "Oculta este elemento enquanto você está em uma montaria de pilotagem aérea (capaz de planar), onde a Blizzard mostra seu HUD de vigor."
