L["Hold a bound key, point or scroll to choose, then release to fire. Escape cancels."] = "Segure uma tecla vinculada, aponte ou role para escolher e solte para disparar. Esc cancela."
L["Hold a key to open a menu of actions; point or scroll to choose, release to fire."] = "Segure uma tecla para abrir um menu de ações; aponte ou role para escolher, solte para disparar."
L["Hold Shift and drag row buttons to nudge them. Reset Button Positions returns them."] = "Segure Shift e arraste os botões da linha para ajustá-los. Redefinir Posições dos Botões os restaura."
L["Hold Shift to drag actions off locked bars."] = "Segure Shift para arrastar ações de barras travadas."
L["Hold Shift to review the Dungeon Finder role check"] = "Segure Shift para revisar a verificação de função do Localizador de Masmorras"
L["Hold Shift to scroll to the top or bottom."] = "Segure Shift para rolar até o topo ou a base."
L["Hold Shift to Skip"] = "Segure Shift para Pular"
L["Hold the key to open, release to fire. Toggle mode keeps the menu open: the Select key fires, the menu key or Escape closes."] = "Segure a tecla para abrir e solte para disparar. O modo Alternar mantém o menu aberto: a tecla Selecionar dispara, a tecla do menu ou Esc fecha."
L["Holds the block at this width and clips longer text, so a plugin whose text keeps changing length never shifts the blocks beside it. Zero sizes the block to whatever the plugin currently says."] = "Mantém o bloco nesta largura e corta textos maiores, para que um plugin cujo texto muda de tamanho nunca desloque os blocos ao lado. Zero ajusta o bloco ao que o plugin mostra no momento."
