L["Include your Blizz UI Enhanced settings from the Window Skins and Tooltips, Menus & Popups tabs. These are account-wide: if the importer opts in, they overwrite that player's settings across ALL of their profiles."] = "Inclui suas configurações do Blizz UI Enhanced das abas Visuais de Janela e Dicas, Menus e Pop-ups. Valem para a conta toda: se quem importar aceitar, elas substituem as configurações dele em TODOS os perfis."
L["Include your complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. On import this replaces the recipient's overrides entirely."] = "Inclui toda a sua configuração de substituições: valores por especialização e condicionais, grupos, layouts do Modo de Desbloqueio e substituições do Gerenciador de Bônus. Ao importar, substitui por completo as do destinatário."
L["Include your Cooldown Manager spell layout (which spells sit on which bars) plus all per-spell settings for any specs you choose."] = "Inclui o layout de feitiços do Gerenciador de Recargas (quais feitiços ficam em quais barras) e todas as configurações por feitiço das especializações escolhidas."
