L["Pick which content these consumable reminders appear in.\nRested areas (cities and inns) always stay hidden."] = "Escolha em qual conteúdo estes lembretes de consumíveis aparecem.\nÁreas de descanso (cidades e estalagens) ficam sempre ocultas."
L["Pick which content these Warlock reminders appear in.\nRested areas (cities and inns) always stay hidden."] = "Escolha em qual conteúdo estes lembretes de Bruxo aparecem.\nÁreas de descanso (cidades e estalagens) ficam sempre ocultas."
L["Pick which content this section's reminders appear in.\nRested areas (cities and inns) always stay hidden."] = "Escolha em qual conteúdo os lembretes desta seção aparecem.\nÁreas de descanso (cidades e estalagens) ficam sempre ocultas."
L["Pick which demons count as correct for Wrong Demon. A demon only counts while its summon spell is known; with none picked (or everything picked), the reminder never fires."] = "Escolha quais demônios contam como corretos para Demônio Errado. Um demônio só conta se o feitiço de invocação for conhecido; sem nenhum escolhido (ou com todos), o lembrete nunca dispara."
