L["Shows incoming heals past the health bar: yours, then other players'."] = "Mostra curas recebidas além da barra de vida: as suas, depois as de outros jogadores."
L["Shows large amounts using K/M suffixes (284,208g becomes 284.2Kg) instead of the full grouped number. The tooltip always shows the exact amount."] = "Mostra valores grandes com sufixos K/M (284,208g vira 284.2Kg) em vez do número completo. A dica sempre mostra o valor exato."
L["Shows only debuffs Blizzard flags as important."] = "Mostra só penalidades que a Blizzard marca como importantes."
L["Shows only debuffs that match every checked Show filter (dispel types count as one); opposites like Non-Player Auras with Cast By You show nothing."] = "Mostra só penalidades que atendem a todos os filtros Mostrar marcados (tipos de dissipação contam como um); opostos como Auras de Não Jogadores com Lançado por Você não mostram nada."
L["Shows only the debuffs you apply that Blizzard also flags as important."] = "Mostra só as penalidades que você aplica e que a Blizzard também marca como importantes."
