L["Shows only this frame's Tracked Auras; add them with Edit Tracked Auras at the top of this menu."] = "Mostra só as Auras Rastreadas deste quadro; adicione-as com Editar Auras Rastreadas no topo deste menu."
L["Shows silver and copper, not just gold."] = "Mostra prata e cobre, não só ouro."
