L["Shows the currency's description text in the tooltip. Turn off for a compact tooltip with just the name and the amount."] = "Mostra o texto de descrição da moeda na dica. Desative para uma dica compacta só com o nome e o valor."
L["Shows the debuffs you apply plus important debuffs from anyone."] = "Mostra as penalidades que você aplica mais penalidades importantes de qualquer um."
L["Shows the frame while this unit is below full health; while enabled, a frame hidden by its visibility setting can still be clicked."] = "Mostra o quadro enquanto esta unidade está abaixo da vida máxima; quando ativado, um quadro oculto pela visibilidade ainda pode ser clicado."
