L["Shows the most important boss debuff (ICC, Ruby Sanctum, ToC, Ulduar, Naxxramas) as a large icon in the middle of the frame."] = "Mostra a penalidade de chefe mais importante (ICC, Ruby Sanctum, ToC, Ulduar, Naxxramas) como um ícone grande no meio do quadro."
