L["Shows the plugin's text. Off leaves an icon-only block that still carries the plugin's tooltip and clicks."] = "Mostra o texto do plugin. Desativado deixa um bloco só com ícone que ainda mantém a dica e os cliques do plugin."
L["Shows the profession icons next to the text."] = "Mostra os ícones de profissão ao lado do texto."
L["Shows the raid target marker icon on boss frames."] = "Mostra o ícone de marcador de alvo de raide nos quadros de chefe."
L["Shows the spec icon next to the text."] = "Mostra o ícone da especialização ao lado do texto."
L["Shows the spell icon over the portrait while casting and lets the bar use the full width."] = "Mostra o ícone do feitiço sobre o retrato durante o lançamento e deixa a barra usar a largura total."
L["Shows the stock rune or combo point frame here instead of the pips."] = "Mostra o quadro original de runas ou pontos de combo aqui em vez dos marcadores."
