L["The Armory"] = "O Arsenal"
L["The background colour behind Dark Mode bars (Unit Frames, Raid Frames, Resource Bars)."] = "A cor de fundo atrás das barras do Modo Escuro (Quadros de Unidade, Quadros de Raide, Barras de Recurso)."
L["The bank opens anywhere from the Bags header; away from a banker it shows the last saved contents."] = "O banco abre de qualquer lugar pelo cabeçalho das Bolsas; longe de um bancário, mostra o último conteúdo salvo."
L["The bar shows stacks out of the maximum instead of time."] = "A barra mostra os acúmulos sobre o máximo em vez do tempo."
