L["The Combat Indicator is not available for the Focus frame."] = "O Indicador de Combate não está disponível para o quadro de Foco."
L["The Cooldown Manager can do far more than show cooldowns, it also has per-spell settings, bar glows, tracking bars and more! Check out some tips and tricks for getting more from it."] = "O Gerenciador de Recargas faz muito mais do que mostrar recargas: ele também tem configurações por feitiço, brilhos de barra, barras de rastreamento e mais! Confira algumas dicas e truques para aproveitá-lo melhor."
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "O idioma de exibição do painel de opções do EllesmereUI. Automático segue o seu cliente do jogo. Textos não traduzidos aparecem em inglês."
L["the EllesmereUI theme"] = "o tema EllesmereUI"
L["The exact inverse of Skyriding (Airborne): anything that is not airborne on a glide-capable mount or flight form, standing on the ground included."] = "O inverso exato de Voo Dinâmico (No Ar): qualquer situação que não seja estar no ar em uma montaria capaz de planar ou forma de voo, incluindo estar no chão."
L["The fallback must differ from\nthe main anchor target"] = "O substituto deve ser diferente\ndo alvo da âncora principal"
L["The flat fill colour bars use when Dark Mode is enabled (Unit Frames, Raid Frames, Resource Bars)."] = "A cor de preenchimento sólida usada pelas barras quando o Modo Escuro está ativado (Quadros de Unidade, Quadros de Raide, Barras de Recurso)."
L["the Frame Source to be EllesmereUI"] = "a Fonte do Quadro ser EllesmereUI"
L["The gem could not be socketed."] = "A gema não pôde ser engastada."
L["The glow line is not shown on a vertical fill or with the From Left Edge placement"] = "A linha de brilho não aparece com preenchimento vertical ou com o posicionamento A Partir da Borda Esquerda"
L["The glow line is not shown on a vertical fill or with the From Right Edge placement"] = "A linha de brilho não aparece com preenchimento vertical ou com o posicionamento A Partir da Borda Direita"
L["The glow line is not shown with Absorb Style None"] = "A linha de brilho não aparece com Estilo de Absorção Nenhum"
L["The Lich King"] = "O Lich Rei"
L["the Modern background style"] = "o estilo de fundo Moderno"
L["The native social window with class icons, class-coloured names, faction banners and invite auto-accept; friend actions and every social tab stay native."] = "A janela social nativa com ícones de classe, nomes na cor da classe, estandartes de facção e aceitação automática de convites; as ações de amigos e todas as abas sociais continuam nativas."
L["The original frames, rings and slots where the game has them, with EllesmereUI's features."] = "Os quadros, anéis e espaços originais onde o jogo os possui, com os recursos do EllesmereUI."
L["The override group '%s' already provides the custom unlock mode for your current spec. Customize it there, or remove this spec from that group."] = "O grupo de sobreposição '%s' já fornece o modo de desbloqueio personalizado para sua especialização atual. Personalize-o lá ou remova esta especialização daquele grupo."
L["The pasted string could not be read completely. Please paste it again."] = "O texto colado não pôde ser lido por completo. Cole-o novamente."
L["The personal resource display's bar frame, or the classic cast bar frame, on the health, power and class resource bars, with every EllesmereUI bar feature."] = "O quadro de barra do display de recursos pessoais, ou o quadro clássico da barra de lançamento, nas barras de vida, poder e recurso de classe, com todos os recursos de barra do EllesmereUI."
L["The Pixel Glow settings this bar's per-icon glows use. The template never changes them."] = "As configurações de Brilho de Pixel usadas pelos brilhos por ícone desta barra. O modelo nunca as altera."
L["the Randomly trigger"] = "o gatilho Aleatoriamente"
L["The Ring of Valor"] = "O Anel do Valor"
L["The scriptProfile CVar is enabled."] = "A CVar scriptProfile está ativada."
