L["The taintLog CVar is enabled."] = "A CVar taintLog está ativada."
L["The tracker always hides in arenas"] = "O rastreador sempre se oculta em arenas"
L["These are the same settings found on each module's own pages, not separate ones."] = "Estas são as mesmas configurações das páginas de cada módulo, não configurações separadas."
L["These settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Estas configurações priorizam a taxa de quadros e a clareza visual em vez dos detalhes do ambiente. As texturas continuam em alta qualidade para que seu personagem e o mundo ainda fiquem perfeitos."
L["These specs hold override values that no group's editing mode can reach anymore (left behind by membership changes). They still apply. Remove one to return that spec to the shared default."] = "Estas especializações têm valores de sobreposição que nenhum modo de edição de grupo alcança mais (deixados por mudanças de membros). Eles ainda se aplicam. Remova um para devolver essa especialização ao padrão compartilhado."
