L["Thin Line Bottom"] = "Linha Fina na Base"
L["Thin Line Top"] = "Linha Fina no Topo"
L["This bar sizes its blocks itself, so the width is not this block's to choose."] = "Esta barra dimensiona os próprios blocos, então a largura não é definida por este bloco."
L["This bar will only show if you have an enemy targeted"] = "Esta barra só aparece se você tiver um inimigo como alvo"
L["This block is already the 'Fill Remaining Space' block. Check another block to move the role."] = "Este bloco já é o bloco 'Preencher Espaço Restante'. Marque outro bloco para mover a função."
L["This can't change which spells the user tracks in Blizzard's CDM.\nIt's recommended to also share your Blizzard CDM layout for any spec you choose here."] = "Isto não altera quais feitiços o usuário rastreia no CDM da Blizzard.\nRecomenda-se também compartilhar seu layout do CDM da Blizzard para cada especialização escolhida aqui."
L["This cannot be undone. Consider exporting this profile as a backup first."] = "Isto não pode ser desfeito. Considere exportar este perfil como backup antes."
L["This cannot be undone. Export your own profile as a backup first."] = "Isto não pode ser desfeito. Exporte seu próprio perfil como backup antes."
L["This condition is coming in a future update."] = "Esta condição chegará em uma atualização futura."
L["This conditional is not active right now. Meet one of its conditions first (for example, enter the dungeon) so you can arrange the layout in its real context."] = "Esta condicional não está ativa agora. Atenda a uma de suas condições primeiro (por exemplo, entre na masmorra) para organizar o layout no contexto real."
L["This control recently changed direction: it now copies FROM the frame you choose. Confirming will copy all shared settings FROM %1$s TO %2$s."] = "Este controle mudou de direção recentemente: agora ele copia DO quadro que você escolher. Confirmar copiará todas as configurações compartilhadas DE %1$s PARA %2$s."
L["This element cannot use group-based visibility."] = "Este elemento não pode usar visibilidade baseada em grupo."
L["This element doesn't support both Height and Width matching"] = "Este elemento não suporta correspondência de Altura e Largura ao mesmo tempo"
L["This element shows as soon as ONE Show condition matches. Hide keeps its meaning in both match modes: a checked Hide always hides, on every row."] = "Este elemento aparece assim que UMA condição de Mostrar for atendida. Ocultar mantém o significado nos dois modos: um Ocultar marcado sempre oculta, em todas as linhas."
L["This element will only show while you are inside a house or plot"] = "Este elemento só aparece enquanto você estiver dentro de uma casa ou lote"
L["This element will only show while you are mounted"] = "Este elemento só aparece enquanto você estiver montado"
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "Esta exportação inclui configurações entre perfis que sobrescreverão as configurações de quem importar, incluindo Qualidade de Vida, Hovercast e outras que normalmente não devem ser compartilhadas com perfis comuns. ISTO NÃO É RECOMENDADO para compartilhar perfis publicamente."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\n"] = "Este recurso otimiza suas configurações gráficas no jogo para oferecer a melhor combinação de FPS alto e clareza visual.\n\nVocê pode reverter todas as alterações a qualquer momento clicando em \"Restaurar Minhas Configurações\", que aparecerá após a otimização.\n\n\nO que alteramos:\n\n"
L["This feature requires Snap Elements to be enabled"] = "Este recurso requer que Encaixar Elementos esteja ativado"
L["This frame's source changes require a UI reload to take effect."] = "As alterações de fonte deste quadro exigem recarregar a interface para ter efeito."
L["This glow is locked on its settings page."] = "Este brilho está travado na página de configurações dele."
L["This group's custom Buff Manager can only be activated or edited while playing one of its specs."] = "O Gerenciador de Bônus personalizado deste grupo só pode ser ativado ou editado jogando com uma de suas especializações."
L["This group's custom Debuff Manager can only be activated or edited while playing one of its specs."] = "O Gerenciador de Penalidades personalizado deste grupo só pode ser ativado ou editado jogando com uma de suas especializações."
L["This is a CDM Bar Layout string, not a profile string."] = "Este é um texto de Layout de Barras do CDM, não um texto de perfil."
L["This is an old CDM Bar Layout string. This format is no longer supported. Use the standard profile import instead."] = "Este é um texto antigo de Layout de Barras do CDM. Este formato não é mais suportado. Use a importação de perfil padrão."
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "Esta é a Janela de Fila de Feitiços; ela ajuda a garantir que você não enfileire feitiços demais de uma vez, o que deixa o jogo com sensação de atraso. O recomendado geralmente é no mínimo 200 + seu ping local. Se não tiver certeza do que esta configuração faz, deixe em 400."
L["This is where you can control the settings of Unlock Mode.\n\nElements can be repositioned by dragging or arrow keys (+shift)\nAnchor, Height Match, or Width match any element.\nSnapping is based on closest element, but you can snap only to\n a specific element via right click or the settings icon."] = "Aqui você controla as configurações do Modo de Desbloqueio.\n\nOs elementos podem ser reposicionados arrastando ou com as setas (+shift)\nAncore, iguale a Altura ou iguale a Largura de qualquer elemento.\nO encaixe é baseado no elemento mais próximo, mas você pode encaixar só em\n um elemento específico com clique direito ou pelo ícone de configurações."
L["This makes it so the width of the cast bar includes the icon, rather than placing it to the left of the cast bars width."] = "Faz com que a largura da barra de lançamento inclua o ícone, em vez de posicioná-lo à esquerda da largura da barra."
L["This module can't be overridden. Exit the override editing session to open it."] = "Este módulo não pode ser sobreposto. Saia da sessão de edição de sobreposição para abri-lo."
L["This module is excluded from Spec Overrides."] = "Este módulo está excluído das Sobreposições de Especialização."
L["This option can't be used while Blizzard Class Resource Art is enabled in Resource Bars."] = "Esta opção não pode ser usada enquanto a Arte de Recurso de Classe da Blizzard estiver ativada em Barras de Recurso."
L["This option does not apply to the player frame."] = "Esta opção não se aplica ao quadro do jogador."
L["This option is not available on the player frame"] = "Esta opção não está disponível no quadro do jogador"
L["This option is only available for formats that display a percentage."] = "Esta opção só está disponível para formatos que exibem porcentagem."
L["This option is only available for the Custom Color Theme"] = "Esta opção só está disponível para o Tema de Cor Personalizado"
L["This option is only available when Portrait Mode is Detached."] = "Esta opção só está disponível quando o Modo de Retrato é Destacado."
L["This option only affects Raid Buffs you can cast"] = "Esta opção só afeta Bônus de Raide que você pode lançar"
L["This option only applies to the Badge style."] = "Esta opção só se aplica ao estilo Emblema."
L["This option only applies when Name > Target is selected."] = "Esta opção só se aplica quando Nome > Alvo está selecionado."
L["This option only applies when Name > Target or Target is selected."] = "Esta opção só se aplica quando Nome > Alvo ou Alvo está selecionado."
L["This option only applies when Target is selected."] = "Esta opção só se aplica quando Alvo está selecionado."
L["This option only applies when the text shows a name."] = "Esta opção só se aplica quando o texto mostra um nome."
L["This option requires %1$s to be %2$s"] = "Esta opção requer que %1$s seja %2$s"
L["This option requires a 2D Portrait or Class Art Style."] = "Esta opção requer um Retrato 2D ou o Estilo de Arte de Classe."
L["This option requires a Border Size above 0"] = "Esta opção requer um Tamanho de Borda acima de 0"
L["This option requires a Border Size above 0."] = "Esta opção requer um Tamanho de Borda acima de 0."
L["This option requires a Border Style other than Inherit (Main Frames)."] = "Esta opção requer um Estilo de Borda diferente de Herdar (Quadros Principais)."
L["This option requires a Border Style other than Solid."] = "Esta opção requer um Estilo de Borda diferente de Sólido."
L["This option requires a border style with divider art and a Border Size above 0."] = "Esta opção requer um estilo de borda com arte divisória e um Tamanho de Borda acima de 0."
L["This option requires a Circle or Pixels Circle Shape."] = "Esta opção requer o Formato Círculo ou Círculo de Pixels."
L["This option requires a Class Icon other than None."] = "Esta opção requer um Ícone de Classe diferente de Nenhum."
L["This option requires a detached position to be active."] = "Esta opção requer uma posição destacada ativa."
L["This option requires a Dispel Overlay, Color Custom Borders or Use Dispel Colors."] = "Esta opção requer Sobreposição de Dissipar, Colorir Bordas Personalizadas ou Usar Cores de Dissipar."
L["This option requires a dropdown selection other than Above Health Bar"] = "Esta opção requer uma seleção diferente de Acima da Barra de Vida"
L["This option requires a Glow Style other than None"] = "Esta opção requer um Estilo de Brilho diferente de Nenhum"
L["This option requires a text position other than none."] = "Esta opção requer uma posição de texto diferente de nenhuma."
L["This option requires a text selection other than none."] = "Esta opção requer uma seleção de texto diferente de nenhuma."
L["This option requires a Type Icon Position other than None"] = "Esta opção requer uma Posição do Ícone de Tipo diferente de Nenhum"
L["This option requires a visible Portrait and Show Icon."] = "Esta opção requer um Retrato visível e Mostrar Ícone."
L["This option requires an attached Power Bar, a Border Size above 0 and a border style with seam art."] = "Esta opção requer uma Barra de Poder anexada, um Tamanho de Borda acima de 0 e um estilo de borda com arte de junção."
L["This option requires an EllesmereUI Target or Focus frame."] = "Esta opção requer um quadro de Alvo ou Foco do EllesmereUI."
L["This option requires an Outer Ring other than None."] = "Esta opção requer um Anel Externo diferente de Nenhum."
L["This option requires Art Style to be set to Class"] = "Esta opção requer que o Estilo de Arte seja Classe"
L["This option requires Blizzard Style to be disabled"] = "Esta opção requer que o Estilo Blizzard esteja desativado"
L["This option requires Class Resource to be set to Modern."] = "Esta opção requer que Recurso de Classe seja Moderno."
L["This option requires Combine Spell Name and Target to be disabled."] = "Esta opção requer que Combinar Nome do Feitiço e Alvo esteja desativado."
L["This option requires Custom Border Style, Show Icon and Make Icon Part of the Bar, with the EllesmereUI style."] = "Esta opção requer Estilo de Borda Personalizado, Mostrar Ícone e Tornar o Ícone Parte da Barra, com o estilo EllesmereUI."
L["This option requires Dispel Type Borders to be enabled."] = "Esta opção requer que Bordas por Tipo de Dissipar estejam ativadas."
L["This option requires Portrait Mode to be set to Detached."] = "Esta opção requer que o Modo de Retrato seja Destacado."
L["This option requires Show Icon and Make Icon Part of the Bar, with the EllesmereUI style."] = "Esta opção requer Mostrar Ícone e Tornar o Ícone Parte da Barra, com o estilo EllesmereUI."
L["This option requires Show Icon and the EllesmereUI style."] = "Esta opção requer Mostrar Ícone e o estilo EllesmereUI."
L["This option requires Show Icon beside the cast bar and the EllesmereUI style."] = "Esta opção requer Mostrar Ícone ao lado da barra de lançamento e o estilo EllesmereUI."
L["This option requires Show Level."] = "Esta opção requer Mostrar Nível."
L["This option requires Solid or a border style with divider art, and a Border Size above 0."] = "Esta opção requer Sólido ou um estilo de borda com arte divisória, e um Tamanho de Borda acima de 0."
L["This option requires the Class Art Style."] = "Esta opção requer o Estilo de Arte de Classe."
L["This option requires the Class Colored Shape Border and Dark Mode."] = "Esta opção requer a Borda de Formato na Cor da Classe e o Modo Escuro."
L["This option requires the position setting to be detached"] = "Esta opção requer que a posição esteja destacada"
L["This option requires the WoW Forever style."] = "Esta opção requer o estilo WoW Forever."
L["This overwrites this frame's current settings. Frame position, visibility, and enable state are not changed."] = "Isto sobrescreve as configurações atuais deste quadro. Posição, visibilidade e estado de ativação do quadro não são alterados."
L["This page is excluded from overrides."] = "Esta página está excluída das sobreposições."
L["This permanently overwrites this profile's settings with the override '%s': its captured settings and its custom Unlock Mode and Buff Manager layouts (where present) become the profile's own baseline for every spec. ALL spec override groups on this profile are then deleted and the UI reloads. Conditional overrides are not affected."] = "Isto sobrescreve permanentemente as configurações deste perfil com a sobreposição '%s': suas configurações capturadas e seus layouts personalizados do Modo de Desbloqueio e do Gerenciador de Bônus (quando existirem) se tornam a base do perfil para todas as especializações. TODOS os grupos de sobreposição de especialização deste perfil são então excluídos e a interface é recarregada. Sobreposições condicionais não são afetadas."
L["This profile string does not carry any global settings."] = "Este texto de perfil não contém configurações globais."
L["This profile string does not carry any override data."] = "Este texto de perfil não contém dados de sobreposição."
L["This profile string does not carry any Window & Tooltip Skins settings."] = "Este texto de perfil não contém configurações de Visuais de Janelas e Dicas."
L["This profile was created before the beta wipe and is no longer compatible. Please create a new export."] = "Este perfil foi criado antes do reset da beta e não é mais compatível. Crie uma nova exportação."
L["This profile was created with a newer version of EllesmereUI. Please update your addon."] = "Este perfil foi criado com uma versão mais nova do EllesmereUI. Atualize seu addon."
L["This profile was made at %1$d%% UI scale; yours is %2$d%%. Change your UI scale to match the imported profile? This will show all profiles at this scale as UI Scale is not a per-profile setting, but can be changed at any time back to your original value."] = "Este perfil foi feito com escala de interface de %1$d%%; a sua é %2$d%%. Alterar sua escala de interface para corresponder ao perfil importado? Todos os perfis serão exibidos nessa escala, pois a Escala da Interface não é uma configuração por perfil, mas pode ser revertida ao seu valor original a qualquer momento."
L["This resets every EUI addon, not just the current one."] = "Isto redefine todos os addons EUI, não apenas o atual."
L["This setting already has an override for %s"] = "Esta configuração já tem uma sobreposição para %s"
L["This setting can't be overridden."] = "Esta configuração não pode ser sobreposta."
L["This Setting Has Overrides"] = "Esta Configuração Tem Sobreposições"
L["This spec's custom unlock mode is owned by '%s'. Customize it there, or remove the spec from that group."] = "O modo de desbloqueio personalizado desta especialização pertence a '%s'. Personalize-o lá ou remova a especialização daquele grupo."
L["This string is a FULL ACCOUNT export. It replaces your account-wide settings with the sender's, including Quality of Life, HoverCast bindings, Cooldown Manager spell setups, unlock anchors, UI scale, and profile keybinds -- not just a profile. Your other profiles are kept, but a profile with the same name is replaced."] = "Este texto é uma exportação de CONTA COMPLETA. Ele substitui suas configurações da conta inteira pelas do remetente, incluindo Qualidade de Vida, atalhos do HoverCast, configurações de feitiços do Gerenciador de Recargas, âncoras de desbloqueio, escala da interface e atalhos de perfil -- não apenas um perfil. Seus outros perfis são mantidos, mas um perfil com o mesmo nome é substituído."
L["This unit uses the Blizzard default frame -- there are no EllesmereUI settings to configure here."] = "Esta unidade usa o quadro padrão da Blizzard -- não há configurações do EllesmereUI para ajustar aqui."
L["This unit's frame is hidden -- there are no EllesmereUI settings to configure here."] = "O quadro desta unidade está oculto -- não há configurações do EllesmereUI para ajustar aqui."
L["This will create a fully unique Buff Manager for this conditional group. Changes made to your default Buff Manager will no longer affect it."] = "Isto criará um Gerenciador de Bônus totalmente exclusivo para este grupo condicional. Alterações no seu Gerenciador de Bônus padrão não o afetarão mais."
L["This will create a fully unique Buff Manager for this override group. Changes made to your default Buff Manager will no longer affect these specs."] = "Isto criará um Gerenciador de Bônus totalmente exclusivo para este grupo de sobreposição. Alterações no seu Gerenciador de Bônus padrão não afetarão mais estas especializações."
L["This will create a fully unique Debuff Manager for this conditional group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect it."] = "Isto criará um Gerenciador de Penalidades totalmente exclusivo para este grupo condicional. Suas configurações atuais do Gerenciador de Penalidades são copiadas como ponto de partida, e alterações no seu Gerenciador de Penalidades padrão não o afetarão mais."
L["This will create a fully unique Debuff Manager for this override group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect these specs."] = "Isto criará um Gerenciador de Penalidades totalmente exclusivo para este grupo de sobreposição. Suas configurações atuais do Gerenciador de Penalidades são copiadas como ponto de partida, e alterações no seu Gerenciador de Penalidades padrão não afetarão mais estas especializações."
L["This will create a fully unique unlock mode for this conditional group. Changes made to your default unlock mode will no longer affect it."] = "Isto criará um modo de desbloqueio totalmente exclusivo para este grupo condicional. Alterações no seu modo de desbloqueio padrão não o afetarão mais."
L["This will create a fully unique unlock mode for this override group. Changes made to your default unlock mode will no longer affect these specs."] = "Isto criará um modo de desbloqueio totalmente exclusivo para este grupo de sobreposição. Alterações no seu modo de desbloqueio padrão não afetarão mais estas especializações."
L["This will not reset addon-specific Quick Setup."] = "Isto não redefinirá a Configuração Rápida específica de cada addon."
L["This will replace YOUR Blizz UI Enhanced settings (the Window Skins and Tooltips, Menus & Popups tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "Isto substituirá as SUAS configurações do Blizz UI Enhanced (as abas Visuais de Janelas e Dicas, Menus e Pop-ups) pelas de quem compartilhou, em TODOS os seus perfis. Suas configurações atuais nessas duas abas não poderão ser recuperadas depois."
