L["You changed the default value of a setting that has overrides. Overrides keep their own values, so this change will not reach the specs or conditions they cover. To change it for an override, pick that override from the class glyph beside the module search bar and edit it there."] = "Você alterou o valor padrão de uma configuração que tem substituições. As substituições mantêm seus próprios valores, então esta mudança não chegará às especializações ou condições que elas cobrem. Para alterá-la numa substituição, escolha essa substituição no glifo de classe ao lado da busca do módulo e edite lá."
L["You don't have this item in your bags"] = "Você não tem este item nas bolsas"
L["You have not learned %1$s."] = "Você não aprendeu %1$s."
L["You have unsaved position changes.\nWhat would you like to do?"] = "Você tem alterações de posição não salvas.\nO que deseja fazer?"
L["You may only have "] = "Você só pode ter "
L["You've Got Mail!"] = "Você Recebeu Correio!"
L["Your current spec has an assigned profile so you cannot switch to another. Please unassign to switch."] = "Sua especialização atual tem um perfil atribuído, então você não pode trocar para outro. Remova a atribuição para trocar."
L["Your current spec has its own custom Buff Manager, so conditional Buff Managers never apply to it."] = "Sua especialização atual tem seu próprio Gerenciador de Bônus personalizado, então Gerenciadores de Bônus condicionais nunca se aplicam a ela."
L["Your current spec has its own custom Debuff Manager, so conditional Debuff Managers never apply to it."] = "Sua especialização atual tem seu próprio Gerenciador de Penalidades personalizado, então Gerenciadores de Penalidades condicionais nunca se aplicam a ela."
L["Your current spec has its own custom unlock mode, so conditional unlock modes never apply to it. Swap to a spec without one to customize this."] = "Sua especialização atual tem seu próprio modo de desbloqueio personalizado, então modos de desbloqueio condicionais nunca se aplicam a ela. Troque para uma especialização sem um para personalizar isto."
L["Your heals"] = "Suas curas"
L["Your preferred food is out - using a backup you own"] = "Sua comida preferida acabou - usando uma reserva que você possui"
L["Your setup and every EllesmereUI feature carry over; only the look changes. Apply a style to every module in one click, or set each module below. Changing a style reloads the UI."] = "Sua configuração e todos os recursos do EllesmereUI são mantidos; só a aparência muda. Aplique um estilo a todos os módulos com um clique ou defina cada módulo abaixo. Mudar um estilo recarrega a interface."
L["Your UI, Restyled in Seconds"] = "Sua Interface, Renovada em Segundos"
L["Zone"] = "Zona"
L["Zone and Subzone"] = "Zona e Subzona"
