L["|cff00ff00[EllesmereUI]|r All hints reset. /reload to see them again."] = "|cff00ff00[EllesmereUI]|r Todas as dicas redefinidas. Use /reload para vê-las de novo."
L["|cff00ff00[EllesmereUI]|r UI scale reset. /reload to re-snapshot from your Blizzard scale."] = "|cff00ff00[EllesmereUI]|r Escala da interface redefinida. Use /reload para recapturar a partir da sua escala da Blizzard."
L["|cff00ff98EllesmereUI:|r Overrides intro reset. The announcement popup fires on your next /reload; the video guide fires on your next click of the overrides glyph."] = "|cff00ff98EllesmereUI:|r Introdução das substituições redefinida. O pop-up de anúncio aparece no próximo /reload; o guia em vídeo aparece no próximo clique no glifo de substituições."
L["|cff00ff98EllesmereUI:|r Video guides and tutorial tips reset. Badges are back; one-time popups will fire again."] = "|cff00ff98EllesmereUI:|r Guias em vídeo e dicas de tutorial redefinidos. Os selos voltaram; pop-ups únicos aparecerão novamente."
L["|cff0cd29dLeft-click:|r |cffE0E0E0Toggle EllesmereUI|r"] = "|cff0cd29dClique esquerdo:|r |cffE0E0E0Alternar EllesmereUI|r"
L["|cff0cd29dMiddle-click:|r |cffE0E0E0Hide Minimap Button|r"] = "|cff0cd29dClique do meio:|r |cffE0E0E0Ocultar Botão do Minimapa|r"
L["|cff0cd29dRight-click:|r |cffE0E0E0Enter Unlock Mode|r"] = "|cff0cd29dClique direito:|r |cffE0E0E0Entrar no Modo de Desbloqueio|r"
