L["|cffff6060[EllesmereUI]|r Cannot enter Unlock Mode during combat."] = "|cffff6060[EllesmereUI]|r Não é possível entrar no Modo de Desbloqueio em combate."
L["|cffff6060[EllesmereUI]|r Cannot open options during combat. Use /eui to view Patch Notes."] = "|cffff6060[EllesmereUI]|r Não é possível abrir as opções em combate. Use /eui para ver as Notas de Atualização."
L["|cffff6060[EllesmereUI]|r Cannot rename to \"Default\"."] = "|cffff6060[EllesmereUI]|r Não é possível renomear para \"Default\"."
